"use client";

import { useEffect, useRef, useState } from "react";
import { useBookingContext } from "@/src/components/Booking/BookingContext";

export default function TrialMakeupPopup() {
  const [isOpen, setIsOpen] = useState(false);
  const overlayRef = useRef(null);
  const dialogRef = useRef(null);
  const openBtnRef = useRef(null);
  const { openForm } = useBookingContext();

  const closeModal = () => {
    setIsOpen(false);
    document.body.style.overflow = "";
  };

  const openModal = () => {
    setIsOpen(true);
    document.body.style.overflow = "hidden";
    setTimeout(() => dialogRef.current?.focus(), 0);
  };

  const handleBookNow = () => {
    closeModal();
    openForm();
  };

  useEffect(() => {
    const alreadyShown = sessionStorage.getItem("trial-makeup-popup-shown");

    if (!alreadyShown) {
      const timer = setTimeout(() => {
        openModal();
        sessionStorage.setItem("trial-makeup-popup-shown", "true");
      }, 1200);

      return () => clearTimeout(timer);
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isOpen) return;

      if (e.key === "Escape") closeModal();

      if (e.key === "Tab") {
        const focusable = dialogRef.current?.querySelectorAll(
          "button, [href], input, select, textarea, [tabindex]:not([tabindex='-1'])"
        );

        if (!focusable || focusable.length === 0) return;

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div
      id="trialPopupOverlay"
      ref={overlayRef}
      onClick={(e) => e.target.id === "trialPopupOverlay" && closeModal()}
      className="fixed inset-0 z-[1100] flex items-center justify-center p-4 before:fixed before:inset-0 before:bg-black/55"
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="trial-popup-title"
        tabIndex={-1}
        className="relative z-[1101] w-full max-w-md overflow-hidden rounded-2xl bg-white shadow-2xl outline-none"
      >
        <button
          type="button"
          aria-label="Close popup"
          onClick={closeModal}
          className="absolute right-4 top-4 flex h-9 w-9 items-center justify-center rounded-full bg-white/90 text-gray-700 shadow-md transition hover:bg-white"
        >
          ✕
        </button>

        <div className="bg-gradient-to-r from-fuchsia-700 via-pink-600 to-orange-400 px-6 py-8 text-center text-white">
          <h2 id="trial-popup-title" className="text-2xl font-extrabold leading-snug">
            Book a Free Trial Makeup Now!
          </h2>
        </div>

        <div className="px-6 py-6 text-center">
          <p className="text-base leading-7 text-gray-700">
            ✨ Enjoy a <span className="font-bold text-fuchsia-700">FREE makeup trial</span> with
            our top stylists and feel like a star! 💄 Limited time offer — book your session today
            and let us bring out your natural beauty! 🌟
          </p>

          <div className="mt-6 flex flex-col gap-3 sm:flex-row">
            <button
              type="button"
              onClick={handleBookNow}
              className="w-full rounded-xl bg-gradient-to-r from-fuchsia-700 to-pink-600 px-4 py-3 text-sm font-semibold text-white transition hover:opacity-95"
            >
              Book Now
            </button>

            <button
              type="button"
              onClick={closeModal}
              className="w-full rounded-xl border border-gray-300 bg-white px-4 py-3 text-sm font-semibold text-gray-800 transition hover:bg-gray-50"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}